def helper_add_lock_unlock_event_to_queue(client, message_type: str, org_id, skip_notification: bool = False):
    """Add event to the Queue."""
    queue_payload = {
        'accountId': org_id,
        'accountName': 'DEV - PAD01',
        'suspensionReasonCode': 'OWNER_CHANGE'
    }
    if skip_notification:
        queue_payload['skipNotification'] = True
    payload = build_request_for_queue_push(message_type, queue_payload)
    post_to_queue(client, payload)

@classmethod
    def unlock_overdue_accounts(cls):
        """Check and unlock overdue EFT accounts."""
        for (payment_account_id, payment_account) in cls.overdue_account_ids.items():
            if InvoiceService.has_overdue_invoices(payment_account_id):
                continue
            payment_account.has_overdue_invoices = None
            payment_account.save()
            AuthEvent.publish_unlock_account_event(payment_account)
